using System.Collections;
using System.IO;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using System.Collections.Generic;
[InitializeOnLoad] public static class StorybookRebirthSequenceValidation{
 const string Out="output/rebirth-sequence/";static bool running;static double started;
 static StorybookRebirthSequenceValidation(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("REBIRTH_SEQUENCE_QA",false)){SessionState.SetBool("REBIRTH_SEQUENCE_QA",false);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",false);running=false;}};}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(Out+"validate.request")){File.Delete(Out+"validate.request");File.WriteAllText(Out+"validation.txt","");UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/MainScenes/Gameplay.unity");SessionState.SetBool("REBIRTH_SEQUENCE_QA",true);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",true);EditorApplication.isPlaying=true;}if(EditorApplication.isPlaying&&SessionState.GetBool("REBIRTH_SEQUENCE_QA",false)&&!running&&GameManager.single&&GameplayCanvas.single){running=true;started=EditorApplication.timeSinceStartup;GameManager.single.StartCoroutine(Run());}if(running&&EditorApplication.timeSinceStartup-started>180){Check(false,"timeout");EditorApplication.isPlaying=false;}}
 static void Error(string message,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error)Check(false,message);}
 static void Check(bool ok,string s)=>File.AppendAllText(Out+"validation.txt",(ok?"PASS ":"FAIL ")+s+"\n");
 static IEnumerator Run(){Application.logMessageReceived+=Error;var intro=Object.FindAnyObjectByType<CursedBookIntro>(FindObjectsInactive.Include);while(intro&&intro.gameObject.activeSelf)yield return null;yield return new WaitForSecondsRealtime(1);var gc=GameplayCanvas.single;gc.CancelInvoke("TryShowingXpBoosterNotification");gc.xpBoosterNotification.SetActive(false);gc.dailyCherriesPop.SetActive(false);TutorialManager.single.automatic=false;TutorialManager.single.view.Hide();var ui=gc.homeUI.settingsUI;
 var gm=GameManager.single;for(int i=0;i<20;i++)if(!gm.HasSeenThis("Tutorial-"+i))gm.thingsSeenPermanent.Add("Tutorial-"+i);
 foreach(var size in new[]{new Vector2Int(1080,1920),new Vector2Int(768,1024),new Vector2Int(720,1440)}){gm.playerLevel=60;gm.rebirthLevel=0;gm.stackedXp=gm.stackedCrystals=0;StorybookEquipmentValidation.Resolution(size.x,size.y);Router.single.CallRebirthFromCamp();yield return new WaitForSecondsRealtime(3);var owner=RebirthPackage.single;Check(owner&&owner.sequence,"New sequence bound "+size);owner.ToggleAreYouSure(true);owner.RebirthButton();owner.RebirthButton();Check(gm.playerLevel==1&&gm.rebirthLevel==1&&gm.statPoints==10&&gm.skillPoints==3,"Rebirth applied exactly once "+size);yield return new WaitForSecondsRealtime(1.6f);Check(owner.sequence.gameObject.activeInHierarchy&&!owner.rebirthCanvas.activeSelf,"New sequence visible "+size);yield return new WaitForEndOfFrame();var image=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Out+"opening-"+size.x+"x"+size.y+".png",image.EncodeToPNG());Object.Destroy(image);yield return new WaitForSecondsRealtime(2.8f);Check(owner.sequence.title.text=="故事，再次开始"&&owner.sequence.subjectNumber.text=="No. "+gc.homeUI.subjectNumber,"Live completion text and subject number");yield return new WaitForEndOfFrame();image=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Out+"renewal-"+size.x+"x"+size.y+".png",image.EncodeToPNG());Object.Destroy(image);yield return new WaitForSecondsRealtime(3);Check(!RebirthPackage.single&&gc.homeUI.gameObject.activeInHierarchy&&!TransitionCanvas.single.group.blocksRaycasts,"Automatic return and input release "+size);}
 StorybookEquipmentValidation.Resolution(1080,1920);File.AppendAllText(Out+"validation.txt","DONE\n");Application.logMessageReceived-=Error;EditorApplication.isPlaying=false;}
}
